if 'df' not in st.session_state:
    st.session_state.df = load_data()

df = st.session_state.df

st.title("🛒 Евиденција на Цени и Пазарење")
st.markdown("Добредојдовте! Ова е вашата лична база за најниски цени по производи.")

tab1, tab2 = st.tabs(["🔍 Пребарувај цени", "➕ Додај нов производ / сметка"])

with tab1:
    st.subheader("Преглед на најниски цени")
    
    search_query = st.text_input("Пребарај производ или маркет:", "")
    
    categories = ["Сите"] + sorted(df['Категорија'].unique().tolist())
    selected_category = st.selectbox("Филтрирај по категорија:", categories)
    
    filtered_df = df.copy()
    
    if search_query:
        mask = filtered_df['Производ и грамажа'].str.contains(search_query, case=False, na=False) | \
               filtered_df['Маркет'].str.contains(search_query, case=False, na=False)
        filtered_df = filtered_df[mask]
        
    if selected_category != "Сите":
        filtered_df = filtered_df[filtered_df['Категорија'] == selected_category]
        
    st.dataframe(filtered_df, use_container_width=True, hide_index=True)
    st.info(f"Вкупно прикажани производи: {len(filtered_df)}")

with tab2:
    st.subheader("Додај или ажурирај производ")
    with st.form("add_form"):
        cat = st.selectbox("Категорија", sorted(df['Категорија'].unique().tolist()))
        prod = st.text_input("Име на производ и грамажа (на пр. Млеко 1л)")
        price = st.number_input("Цена (ден.)", min_value=0.0, step=1.0)
        market = st.selectbox("Маркет", ["Ramstore", "КАМ", "Пакет", "Јоцо Мес", "Друго"])
        date_str = st.date_input("Датум", datetime.today()).strftime("%d.%m.%Y")
        note = st.text_input("Забелешка (опционално)", "")
        
        submitted = st.form_submit_button("Зачувај во базата")
        
        if submitted:
            if prod and price > 0:
                prod_clean = prod.strip()
                existing = df[df['Производ и грамажа'].str.lower() == prod_clean.lower()]
                
                if not existing.empty:
                    old_price = existing['Најниска цена (ден.)'].values[0]
                    if price < old_price:
                        df.loc[df['Производ и грамажа'].str.lower() == prod_clean.lower(), 'Најниска цена (ден.)'] = price
                        df.loc[df['Производ и грамажа'].str.lower() == prod_clean.lower(), 'Маркет'] = market
                        df.loc[df['Производ и грамажа'].str.lower() == prod_clean.lower(), 'Датум'] = date_str
                        df.loc[df['Производ и грамажа'].str.lower() == prod_clean.lower(), 'Забелешка'] = f"Намалено од {old_price}"
                        st.success(f"Цената за '{prod_clean}' е ажурирана со нова ПОНИСКА цена: {price} ден. ({market})!")
                    else:
                        st.warning(f"Производот веќе постои со пониска или иста цена ({old_price} ден.). Цената не е променета.")
                else:
                    new_row = pd.DataFrame([{
                        'Категорија': cat,
                        'Производ и грамажа': prod_clean,
                        'Најниска цена (ден.)': price,
                        'Маркет': market,
                        'Датум': date_str,
                        'Забелешка': note
                    }])
                    df = pd.concat([df, new_row], ignore_index=True)
                    df = df.sort_values(by=['Категорија', 'Производ и грамажа'])
                    st.session_state.df = df
                    st.success(f"Успешно додаден нов производ: {prod_clean} ({price} ден.)!")
            else:
                st.error("Ве молиме внесете име на производ и валидна цена.")

    st.subheader("Преземи ажурирана табела")
    csv = df.to_csv(index=False).encode('utf-8-sig')
    st.download_button(
        label="📥 Преземи како CSV / Excel компатибилен фајл",
        data=csv,
        file_name="Evidencija_Ceni_Pazaranje_Online.csv",
        mime="text/csv",
    )
